import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, vec3, uniform, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D, PointLight, ShadowMaterial, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    gsap.killTweensOf([group.position, group.scale, group.rotation]);
    group.traverse((node) => {
      if (node.material?.dispose) node.material.dispose();
      if (node.geometry?.dispose) node.geometry.dispose();
    });
  };

  // Placeholder mesh container
  const meshContainer = new Object3D();
  group.add(meshContainer);

  // Load GLB mesh
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      scene.traverse((node) => {
        if (node.isMesh) {
          node.castShadow = true;
          node.receiveShadow = true;
        }
      });
      meshContainer.add(scene);

      // Scale and center mesh
      const bbox = new ctx.THREE.Box3().setFromObject(scene);
      const size = bbox.getSize(new Vector3());
      const maxDim = Math.max(size.x, size.y, size.z);
      const scale = 1.2 / maxDim;
      scene.scale.multiplyScalar(scale);
      bbox.setFromObject(scene);
      const center = bbox.getCenter(new Vector3());
      scene.position.sub(center);
    });
  }

  // Accent rim light (orange-red to match signal accent)
  const rimLight = new PointLight(0xff2a38, 1.2, 4);
  rimLight.position.set(1.5, 1.2, 1.8);
  group.add(rimLight);

  // Ambient fill
  const fillLight = new PointLight(0xffffff, 0.5, 5);
  fillLight.position.set(-1.2, -0.8, 0.6);
  group.add(fillLight);

  // Contact shadow plane (radial, subtle)
  const shadowPlane = new Mesh(
    new PlaneGeometry(1.4, 1.4),
    new ShadowMaterial({ opacity: 0.45 })
  );
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.y = -0.65;
  shadowPlane.receiveShadow = true;
  group.add(shadowPlane);

  // Apply cinematic primitives
  const primitives = [];

  // Parallax scroll (trigger: scroll)
  const parallaxResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.4,
  });
  if (parallaxResult) primitives.push(parallaxResult);

  // Magnetic cursor (trigger: hover)
  const magneticResult = ctx.primitives['magnetic-cursor'](group, {
    radius: 1.2,
    strength: 0.35,
  });
  if (magneticResult) primitives.push(magneticResult);

  // Entrance animation: weighted settle
  const startY = group.position.y + 0.15;
  group.position.y = startY;
  const entranceTl = gsap.timeline();
  entranceTl.to(
    group.position,
    {
      y: group.position.y - 0.15,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );
  entranceTl.to(
    group.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
      overshoot: 1.04,
    },
    0
  );

  // Hover interaction: rise-in effect
  group.userData.handlers.hover = {
    enter: () => {
      gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      gsap.to(group.scale, {
        x: 1.08,
        y: 1.08,
        z: 1.08,
        duration: 0.4,
        ease: 'back.out',
        overwrite: 'auto',
      });
    },
    exit: () => {
      gsap.to(group.position, {
        y: group.position.y - 0.15,
        duration: 0.5,
        ease: 'power2.inOut',
        overwrite: 'auto',
      });
      gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.5,
        ease: 'power2.inOut',
        overwrite: 'auto',
      });
    },
  };

  // Click interaction: navigate to hub-features.select
  group.userData.handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-features', action: 'select' });
  };

  // Wrap cleanup to include primitives
  const originalCleanup = group.userData.cleanup;
  group.userData.cleanup = () => {
    originalCleanup();
    primitives.forEach((p) => {
      if (p.cleanup) p.cleanup();
    });
    gsap.killTweensOf([group.position, group.scale, group.rotation]);
    entranceTl.kill();
  };

  return group;
}
